FAM = {  # id: (nume ro,en,es), text ro,en,es
 "01": (("Colorimetrie", "Colorimetry", "Colorimetría"),
        ("Verifici acuratețea unei transformări pe 24 de pătrate de referință, pe 21 de trepte neutre, pe primare, pe traiectorii de nuanță și pe puncte de stres de gamut. Variantele extinse adaugă felii LCh, limite de gamut și o scară ΔE.",
         "Check a transform's accuracy on 24 reference patches, 21 neutral steps, primaries, hue trajectories and gamut-stress points. The extended variant adds LCh slices, gamut boundaries and a ΔE ladder.",
         "Compruebas la exactitud de una transformación con 24 parches de referencia, 21 escalones neutros, primarios, trayectorias de matiz y puntos de estrés de gamut. La variante extendida añade cortes LCh, límites de gamut y una escala ΔE.")),
 "02": (("Piele", "Skin", "Piel"),
        ("02A are valori construite pentru tonuri de piele: grilă ITA, iluminanți, expunere și traiectorii. 02B este un bust sintetic, o ILUSTRAȚIE pentru a testa măști spațiale, fără valori de referință.",
         "02A holds constructed skin-tone values: ITA grid, illuminants, exposure and trajectories. 02B is a synthetic bust, an ILLUSTRATION for testing spatial masks, with no reference values.",
         "02A contiene valores construidos de tonos de piel: rejilla ITA, iluminantes, exposición y trayectorias. 02B es un busto sintético, una ILUSTRACIÓN para probar máscaras espaciales, sin valores de referencia.")),
 "03": (("Expunere", "Exposure", "Exposición"),
        ("Trepte de 1 stop, 1/3 stop și Zone System, culoare în funcție de expunere, headroom și rampe continue în stopuri logaritmice sau liniare. Arată unde se comprimă sau se schimbă tonurile.",
         "Patch ladders in 1-stop, 1/3-stop and Zone System steps, colour versus exposure, headroom, and continuous ramps in log or linear stops. They show where tones compress or shift.",
         "Escalas de 1 stop, 1/3 de stop y Zone System, color frente a exposición, headroom y rampas continuas en stops logarítmicos o lineales. Muestran dónde se comprimen o se desplazan los tonos.")),
 "04": (("Saturație și nuanță", "Saturation and hue", "Saturación y matiz"),
        ("Baleiaje de saturație la luminanță constantă sau variabilă, roți de nuanță și chroma, rampe de nuanță, liniaritatea nuanței și interacțiunea nuanță × luminanță. Util pentru a depista deplasări de nuanță.",
         "Saturation sweeps at constant or variable luminance, hue and chroma wheels, hue ramps, hue linearity and hue × luminance interaction. Useful for spotting hue skews.",
         "Barridos de saturación a luminancia constante o variable, ruedas de matiz y croma, rampas de matiz, linealidad del matiz e interacción matiz × luminancia. Útil para detectar desviaciones de matiz.")),
 "05": (("Balans de alb", "White balance", "Balance de blancos"),
        ("Iluminanți × reflectanțe, deplasare tint (Duv), cinci metode de adaptare cromatică (CAT) și grile de eroare aproape de neutru, inclusiv piele versus neutru sub diferiți iluminanți.",
         "Illuminants × reflectances, tint shift (Duv), five chromatic-adaptation methods (CATs) and near-neutral error grids, including skin versus neutral under different illuminants.",
         "Iluminantes × reflectancias, desplazamiento de tinte (Duv), cinco métodos de adaptación cromática (CAT) y rejillas de error casi neutras, incluida la piel frente al neutro bajo distintos iluminantes.")),
 "06": (("Halation și bloom", "Halation and bloom", "Halation y bloom"),
        ("Surse punctuale de mărimi și intensități diferite, emițători colorați, muchii, tranziții de contrast, linii neon și veiling glare, pentru a vedea cum se împrăștie lumina în efecte de film sau lentilă.",
         "Point sources of different sizes and intensities, coloured emitters, edges, contrast transitions, neon lines and veiling glare, to see how light spreads in film or lens effects.",
         "Fuentes puntuales de distintos tamaños e intensidades, emisores de color, bordes, transiciones de contraste, líneas de neón y veiling glare, para ver cómo se dispersa la luz en efectos de película o de lente.")),
 "07": (("Focalizare și MTF", "Focus and MTF", "Enfoque y MTF"),
        ("Muchii înclinate pentru metoda slanted-edge, stele Siemens, zone plates, chirp-uri, perechi de linii și muchii de contrast mic, pentru estimări de rezoluție și micro-contrast.",
         "Slanted edges for the slanted-edge method, Siemens stars, zone plates, chirps, line pairs and low-contrast edges, for estimating resolution and micro-contrast.",
         "Bordes inclinados para el método slanted-edge, estrellas de Siemens, zone plates, chirps, pares de líneas y bordes de bajo contraste, para estimar resolución y microcontraste.")),
 "08": (("Grain și zgomot", "Grain and noise", "Grano y ruido"),
        ("08A este referința CURATĂ, fără zgomot. 08B are variante CU zgomot gaussian controlat, cu seed fix, etichetate. Pornești de la curat și compari cu efectul unui instrument de grain sau de reducere a zgomotului.",
         "08A is the CLEAN reference, without noise. 08B has NOISY variants with controlled Gaussian noise and a fixed seed, labelled as such. Start from the clean one and compare with the effect of a grain or denoise tool.",
         "08A es la referencia LIMPIA, sin ruido. 08B tiene variantes CON ruido gaussiano controlado y semilla fija, etiquetadas. Parte de la limpia y compara con el efecto de una herramienta de grano o de reducción de ruido.")),
 "09": (("Umbre", "Shadows", "Sombras"),
        ("Trepte aproape de negru, valori sub negru și negative, scară de crush, rampe de lumină slabă, trecerea prin zero și croma în umbre. Arată unde se pierd sau se colorează umbrele.",
         "Near-black steps, sub-black and negative values, a crush scale, low-light ramps, the zero crossing and shadow chroma. They show where shadows are lost or tinted.",
         "Escalones casi negros, valores bajo el negro y negativos, escala de crush, rampas de poca luz, el cruce por cero y croma en sombras. Muestran dónde se pierden o se tiñen las sombras.")),
 "10": (("Lumini și roll-off", "Highlights and roll-off", "Altas luces y roll-off"),
        ("Trepte și rampe în lumini, lumini saturate, supraîncărcarea unui canal, emițători și sonde de compresie a gamutului. Testează cum se comportă un look sau un DRT la capătul de sus.",
         "Steps and ramps in the highlights, saturated highlights, single-channel overload, emitters and gamut-compression probes. They test how a look or DRT behaves at the top end.",
         "Escalones y rampas en las altas luces, altas luces saturadas, sobrecarga de un canal, emisores y sondas de compresión de gamut. Prueban cómo se comporta un look o un DRT en el extremo superior.")),
 "11": (("Gradienți și banding", "Gradients and banding", "Degradados y banding"),
        ("Rampe neutre foarte înguste și cuantizare simulată la 10, 8 și 6 biți, gradienți de nuanță, croma slabă, gradienți în zone aproape de negru sau alb și gradienți 2D. Dezvăluie banding-ul unui lanț de procesare.",
         "Very narrow neutral ramps with simulated 10, 8 and 6-bit quantisation, hue gradients, low-amplitude chroma, near-black and near-white gradients and 2D gradients. They expose banding in a processing chain.",
         "Rampas neutras muy estrechas con cuantización simulada de 10, 8 y 6 bits, degradados de matiz, croma de baja amplitud, degradados casi negros o blancos y degradados 2D. Revelan el banding de una cadena de procesamiento.")),
 "12": (("Lentilă și optică (sintetic)", "Lens and optics (synthetic)", "Lente y óptica (sintético)"),
        ("Grilă dreaptă pentru distorsiune, câmpuri plate, matrice de puncte și muchii tangențiale/sagitale pe 3×3 poziții de câmp. Sunt modele SINTETICE pentru instrumente de corecție, nu măsurători de obiectiv.",
         "A straight grid for distortion, flat fields, a point-source array and tangential/sagittal edges over 3×3 field positions. They are SYNTHETIC patterns for correction tools, not lens measurements.",
         "Rejilla recta para distorsión, campos planos, matriz de puntos y bordes tangenciales/sagitales en 3×3 posiciones de campo. Son patrones SINTÉTICOS para herramientas de corrección, no mediciones de objetivo.")),
}

